  "content": "import gzip
import hashlib
import io
import json
import time
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

import numpy as np
import pandas as pd

BASE = "https://cdaweb.gsfc.nasa.gov/hapi"
RAW = Path(__file__).resolve().parents[1] / "raw" / "hapi"


def request(url, timeout=600):
    for attempt in range(8):
        try:
            with urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent": "x3i-mhd-claude"}), timeout=timeout) as r:
                return r.read()
        except urllib.error.HTTPError as e:
            body = e.read()
            if b"1201" in body:
                return b""
            err = e
        except Exception as e:
            err = e
        time.sleep(min(10 * 2 ** attempt, 300))
    raise RuntimeError(f"{url}: {err!r}")


def info(dataset):
    path = RAW / "info" / f"{dataset}.json"
    if not path.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(request(f"{BASE}/info?" + urllib.parse.urlencode({"id": dataset})))
    return json.loads(path.read_text())


def columns(dataset, params):
    meta = {p["name"]: p for p in info(dataset)["parameters"]}
    names, fills = ["time"], [None]
    for p in params:
        size = int(np.prod(meta[p].get("size", [1])))
        fill = meta[p].get("fill")
        fill = None if fill in (None, "NaN", "nan") else float(fill)
        names += [p] if size == 1 else [f"{p}_{i}" for i in range(size)]
        fills += [fill] * size
    return names, fills


def chunk(dataset, params, t0, t1):
    tag = hashlib.md5(",".join(params).encode()).hexdigest()[:8]
    path = RAW / dataset / f"{t0:%Y%m%dT%H}_{t1:%Y%m%dT%H}_{tag}.csv.gz"
    if not path.exists():
        q = {"id": dataset, "parameters": ",".join(params), "time.min": f"{t0:%Y-%m-%dT%H:%M:%SZ}",
             "time.max": f"{t1:%Y-%m-%dT%H:%M:%SZ}", "format": "csv"}
        body = request(f"{BASE}/data?" + urllib.parse.urlencode(q))
        if body.lstrip().startswith(b"{"):
            if b"1201" not in body:
                raise RuntimeError(body[:500])
            body = b""
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".tmp")
        with gzip.open(tmp, "wb", compresslevel=6) as f:
            f.write(body)
        tmp.replace(path)
    return path


def load(path, names, fills):
    with gzip.open(path, "rb") as f:
        body = f.read()
    if not body.strip():
        return pd.DataFrame(columns=names)
    df = pd.read_csv(io.BytesIO(body), header=None, names=names, na_values=["NaN", "nan"])
    df["time"] = pd.to_datetime(df["time"], utc=True, format="ISO8601")
    for n, fv in zip(names[1:], fills[1:]):
        x = pd.to_numeric(df[n], errors="coerce")
        if fv is not None:
            x = x.mask(np.isclose(x, fv, rtol=1e-6) | (np.abs(x) >= 1e30))
        df[n] = x
    return df


def fetch(dataset, params, t0, t1, days=None, reduce=None):
    names, fills = columns(dataset, params)
    t0, t1 = pd.Timestamp(t0), pd.Timestamp(t1)
    edges = [t0] if days is None else list(pd.date_range(t0, t1, freq=f"{days}D"))
    if edges[-1] < t1:
        edges.append(t1)
    edges = edges if len(edges) > 1 else [t0, t1]
    out = []
    for a, b in zip(edges[:-1], edges[1:]):
        df = load(chunk(dataset, params, a, b), names, fills)
        out.append(reduce(df) if reduce is not None and len(df) else df)
    out = [o for o in out if len(o)]
    return pd.concat(out, ignore_index=True) if out else pd.DataFrame(columns=names)
"
